import{c as s,Q as t,j as i,m as o}from"./chunks/framework.DGHXLY8X.js";const u=JSON.parse('{"title":"Monitoring a running deployment","description":"","frontmatter":{},"headers":[],"relativePath":"operating/observability.md","filePath":"operating/observability.md","lastUpdated":1780987164000}'),a={name:"operating/observability.md"};function d(r,e,c,n,p,l){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="monitoring-a-running-deployment" tabindex="-1">Monitoring a running deployment <a class="header-anchor" href="#monitoring-a-running-deployment" aria-label="Permalink to &quot;Monitoring a running deployment&quot;">​</a></h1><p>This page covers three operator tasks: scraping Prometheus metrics, consuming real-time SSE events, and filtering structured logs by entity ID.</p><h2 id="scraping-prometheus-metrics" tabindex="-1">Scraping Prometheus metrics <a class="header-anchor" href="#scraping-prometheus-metrics" aria-label="Permalink to &quot;Scraping Prometheus metrics&quot;">​</a></h2><p>VideoNode exposes two metrics endpoints. Use <code>/metrics</code> for Prometheus scraping. It serves the standard text exposition format and, unlike the rest of the API, is unauthenticated: it is registered on the raw mux ahead of the auth middleware, so point your scrape config straight at it.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8090/metrics</span></span></code></pre></div><p>The same series are also available as JSON at <code>/api/metrics</code>, which does require auth. Use it for ad-hoc queries with <code>jq</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode:videonode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8090/api/metrics</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.[].name&#39;</span></span></code></pre></div><p>All metrics use the <code>videonode_</code> prefix. The families include:</p><ul><li><code>videonode_ffmpeg_*</code>: per-stream encoder stats (<code>fps</code>, <code>dropped_frames_total</code>, <code>duplicate_frames_total</code>, <code>processing_speed</code>), labeled by <code>stream_id</code></li><li><code>videonode_producer_*</code>: per-source process stats (<code>rss_bytes</code>, <code>cpu_percent</code>), labeled by <code>source_id</code></li><li><code>videonode_webrtc_*</code> and <code>videonode_srt_*</code>: per-stream egress counters plus per-peer and per-consumer feedback (see below)</li><li><code>videonode_mpp_*</code>: Rockchip MPP device load and utilization (see below)</li></ul><p>To see the full current set, scrape the endpoint directly; the list grows with the deployment.</p><h3 id="webrtc-per-peer-metrics" tabindex="-1">WebRTC per-peer metrics <a class="header-anchor" href="#webrtc-per-peer-metrics" aria-label="Permalink to &quot;WebRTC per-peer metrics&quot;">​</a></h3><p>Each connected WebRTC peer contributes a row of RTCP-feedback series, labeled by <code>stream_id</code> and <code>peer_id</code>. A peer&#39;s rows are removed when it disconnects.</p><table tabindex="0"><thead><tr><th>Metric</th><th>Type</th><th>What</th></tr></thead><tbody><tr><td><code>videonode_webrtc_active_peers</code></td><td>gauge</td><td>Active peers per stream (labeled by <code>stream_id</code> only).</td></tr><tr><td><code>videonode_webrtc_peer_rtcp_packets_total</code></td><td>counter</td><td>RTCP packets received from the peer.</td></tr><tr><td><code>videonode_webrtc_peer_nacks_total</code></td><td>counter</td><td>NACK requests (packet-loss indicator).</td></tr><tr><td><code>videonode_webrtc_peer_plis_total</code></td><td>counter</td><td>PLI requests (decoder asked for a keyframe).</td></tr><tr><td><code>videonode_webrtc_peer_firs_total</code></td><td>counter</td><td>FIR requests (full intra request).</td></tr><tr><td><code>videonode_webrtc_peer_jitter</code></td><td>gauge</td><td>Interarrival jitter in RTP timestamp units. Divide by 90000 for seconds.</td></tr></tbody></table><h3 id="srt-per-consumer-metrics" tabindex="-1">SRT per-consumer metrics <a class="header-anchor" href="#srt-per-consumer-metrics" aria-label="Permalink to &quot;SRT per-consumer metrics&quot;">​</a></h3><p>Each SRT consumer contributes a row labeled by <code>stream_id</code> and <code>consumer_id</code>, removed on disconnect.</p><table tabindex="0"><thead><tr><th>Metric</th><th>Type</th><th>What</th></tr></thead><tbody><tr><td><code>videonode_srt_active_consumers</code></td><td>gauge</td><td>Active consumers per stream (labeled by <code>stream_id</code> only).</td></tr><tr><td><code>videonode_srt_frames_written_total</code></td><td>counter</td><td>Frames written per stream, also labeled by <code>codec</code>.</td></tr><tr><td><code>videonode_srt_consumer_rtt_ms</code></td><td>gauge</td><td>Round-trip time in milliseconds.</td></tr><tr><td><code>videonode_srt_consumer_bandwidth_mbps</code></td><td>gauge</td><td>Send bandwidth in Mbps.</td></tr><tr><td><code>videonode_srt_consumer_packet_loss_rate</code></td><td>gauge</td><td>Packet-loss rate.</td></tr><tr><td><code>videonode_srt_consumer_retransmits_total</code></td><td>counter</td><td>Retransmitted packets.</td></tr><tr><td><code>videonode_srt_consumer_dropped_total</code></td><td>counter</td><td>Dropped packets.</td></tr></tbody></table><h3 id="rockchip-mpp-device-load" tabindex="-1">Rockchip MPP device load <a class="header-anchor" href="#rockchip-mpp-device-load" aria-label="Permalink to &quot;Rockchip MPP device load&quot;">​</a></h3><p>On Rockchip hardware, a collector samples <code>/proc/mpp_service/load</code> every five seconds and publishes two gauges per hardware codec device, labeled by <code>device</code>:</p><ul><li><code>videonode_mpp_device_load</code>: device load percentage.</li><li><code>videonode_mpp_device_utilization</code>: device utilization percentage.</li></ul><p>The collector logs a warning and skips the sample when the proc file is absent, so these series are simply missing on hosts without the Rockchip MPP service.</p><h2 id="inspecting-supervised-processes" tabindex="-1">Inspecting supervised processes <a class="header-anchor" href="#inspecting-supervised-processes" aria-label="Permalink to &quot;Inspecting supervised processes&quot;">​</a></h2><p>VideoNode supervises one OS process per pipeline stage (source, composer, encoder). To list them with live state, query <code>/api/processes</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode:videonode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8090/api/processes</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.processes&#39;</span></span></code></pre></div><p>Each row carries the pool <code>id</code> (<code>source:&lt;id&gt;</code>, <code>composer:&lt;id&gt;</code>, or <code>encoder:&lt;stream-id&gt;</code>), the <code>kind</code> (<code>source</code>, <code>composer</code>, <code>encoder</code>, or <code>daemon</code>), <code>state</code>, <code>pid</code>, <code>restart_count</code>, <code>rss_bytes</code>, and <code>cpu_percent</code>. A <code>self</code> row of kind <code>daemon</code> reports the videonode process itself. Source rows also carry <code>refcount</code> and the <code>consumers</code> holding the device.</p><p>The <code>state</code> field is one of five pool states:</p><ul><li><code>idle</code>: not running.</li><li><code>starting</code>: being started.</li><li><code>running</code>: active.</li><li><code>stopping</code>: being stopped.</li><li><code>error</code>: failed to start or crashed (see <code>last_error</code>).</li></ul><p>To bounce one stage, post to <code>/api/processes/{id}/restart</code> with the pool id:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode:videonode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://localhost:8090/api/processes/source:hdmi0/restart</span></span></code></pre></div><p>Sources and composers are re-applied (the control plane reconnects); a running encoder is bounced, while an idle one with no reader attached is left down.</p><p>For the full schema, see <a href="http://localhost:8090/openapi.json" target="_blank" rel="noreferrer"><code>/openapi.json</code></a>.</p><h2 id="consuming-sse-events" tabindex="-1">Consuming SSE events <a class="header-anchor" href="#consuming-sse-events" aria-label="Permalink to &quot;Consuming SSE events&quot;">​</a></h2><p>To receive real-time lifecycle and status changes, connect to the single multiplexed SSE stream:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode:videonode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -N</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8090/api/events</span></span></code></pre></div><p>Each event carries a typed payload. The two you&#39;ll see most:</p><ul><li><code>entity</code>: a uniform envelope for every per-entity update, discriminated by a <code>type</code> tag of the form <code>&lt;entity&gt;.&lt;action&gt;</code> (for example <code>source.status</code>), where <code>&lt;entity&gt;</code> is <code>source</code>, <code>composer</code>, or <code>stream</code> and <code>&lt;action&gt;</code> is <code>created</code>, <code>updated</code>, <code>deleted</code>, <code>status</code>, <code>metrics</code>, or <code>consumers</code></li><li><code>pipeline-state-changed</code>: fires when the pipeline master switch toggles on or off</li></ul><p>The connection sends a <code>heartbeat</code> every 15 seconds to keep proxies and idle clients alive. For the full event model, see <a href="./../development/events-and-sse">Events and SSE</a>.</p><h2 id="filtering-logs-by-stream" tabindex="-1">Filtering logs by stream <a class="header-anchor" href="#filtering-logs-by-stream" aria-label="Permalink to &quot;Filtering logs by stream&quot;">​</a></h2><p>VideoNode writes structured logs via <code>slog</code>. Each log record&#39;s attributes map to uppercase journal fields.</p><p>To see all fields on recent records:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verbose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --since</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;5 min ago&quot;</span></span></code></pre></div><p>To filter records for one stream:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> STREAM_ID=rtsp-lobby</span></span></code></pre></div><p>To filter by module (e.g., the encoder pipeline):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MODULE=encoder</span></span></code></pre></div><p>To list every stream ID that has produced a log record:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> STREAM_ID</span></span></code></pre></div><p>Use <code>SOURCE_ID</code> and <code>COMPOSER_ID</code> in place of <code>STREAM_ID</code> for source and composer log records respectively.</p>`,47)])])}const k=s(a,[["render",d]]);export{u as __pageData,k as default};
